// Solo se acepta un UUID; los datos se leen de Supabase
const b = $input.first().json.body || $input.first().json;
const id = String(b.oficina_id || '').trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) return [];
return [{ json: { id, origen: String(b.origen || 'web').slice(0, 40) } }];

// Arma el correo para el admin. Si el registro ya se había notificado, Supabase devuelve [] y no sale nada.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const origen = $('Validar id').first().json.origen;
return $input.all().map(i => i.json).filter(o => o && o.id).map(o => {
  const fila = (k, v) => v ? `<tr><td style="padding:6px 0;color:#6B7280;width:38%">${k}</td><td style="padding:6px 0;font-weight:700;color:#111827">${esc(v)}</td></tr>` : '';
  const aprobar = `UPDATE public.oficinas_aliadas SET estado = 'aprobada', aprobada_at = now() WHERE id = '${o.id}';`;
  const rechazar = `UPDATE public.oficinas_aliadas SET estado = 'rechazada' WHERE id = '${o.id}';`;
  const html = `<div style="font-family:Arial,sans-serif;max-width:580px;margin:auto;border:1px solid #E5E7EB;border-radius:16px;overflow:hidden">
<div style="background:#0B4A3F;color:#fff;padding:18px 22px"><b>MAXIMUS<span style="color:#10B981">.</span></b> · Nueva oficina aliada por revisar</div>
<div style="padding:22px;font-size:14px;line-height:1.55;color:#111827">
<table style="width:100%;border-collapse:collapse;font-size:14px">
${fila('Inmobiliaria', o.nombre)}${fila('Responsable', o.responsable)}${fila('WhatsApp', '+' + o.whatsapp)}${fila('Correo', o.email)}${fila('Zona', o.zona)}${fila('Asesores', o.num_asesores)}${fila('Web / Instagram', o.sitio_web)}${fila('Descripción', o.descripcion)}${fila('Se registró desde', origen)}
</table>
<p style="text-align:center;margin:20px 0"><a href="https://wa.me/${o.whatsapp}" style="background:#25D366;color:#fff;text-decoration:none;padding:11px 20px;border-radius:10px;font-weight:bold">Escribirle por WhatsApp</a></p>
<p style="margin:0 0 10px"><b>Para aprobarla:</b> entra al panel → <b>Sitio web → Oficinas aliadas</b>. Ahí puedes publicarla, subir su logo y destacarla.</p>
<p style="margin:0 0 6px;font-size:12px;color:#6B7280">Alternativa: pega esto en el SQL Editor de Supabase.</p>
<pre style="background:#F3F4F6;padding:10px;border-radius:8px;font-size:12px;white-space:pre-wrap">${esc(aprobar)}</pre>
<p style="margin:12px 0 6px"><b>Para rechazarla:</b></p>
<pre style="background:#F3F4F6;padding:10px;border-radius:8px;font-size:12px;white-space:pre-wrap">${esc(rechazar)}</pre>
<p style="font-size:12px;color:#6B7280">Sin logo, en la web aparece con sus iniciales.</p>
</div></div>`;
  return { json: { asunto: `🏢 Nueva oficina aliada por revisar: ${o.nombre} (${o.zona})`, html } };
});
